-- Item combat data (migration 80), generated by tools/import_lsb_item_data.py.
--
-- `item_weapon` carries the damage rating, delay, skill type and damage type of
-- every weapon; `item_mods` carries every item's stat modifiers as
-- (item id, modifier id, value).  Both are LandSandBoat's tables verbatim.
--
-- Item ids are the client's own, so a row here is meaningful for any item Fanxi
-- grants, whether or not it is in the `items` catalogue yet.  Neither table has a
-- foreign key for that reason.

CREATE TABLE IF NOT EXISTS item_weapon (
    item_id    INTEGER PRIMARY KEY,
    skill      INTEGER NOT NULL DEFAULT 0,
    ilvl_skill INTEGER NOT NULL DEFAULT 0,
    delay      INTEGER NOT NULL DEFAULT 0,
    dmg        INTEGER NOT NULL DEFAULT 0,
    dmg_type   INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS item_shield (
    item_id INTEGER PRIMARY KEY,
    size    INTEGER NOT NULL,
    level   INTEGER NOT NULL DEFAULT 0,
    ilevel  INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS item_mods (
    item_id INTEGER NOT NULL,
    mod_id  INTEGER NOT NULL,
    value   INTEGER NOT NULL,
    PRIMARY KEY (item_id, mod_id)
);













































































































































































CREATE INDEX IF NOT EXISTS item_mods_mod ON item_mods(mod_id);
